-- =========================================================================================
-- Migration: 20260917_047_create_tlo_positions_and_extend_assignments.sql
-- Description:
--   1. Creates the master table 'public.tlo_positions' with canonical DepEd positions.
--   2. Populates tlo_positions with verified canonical positions inventory (598 items).
--   3. Synchronizes sequence tlo_positions_id_seq.
--   4. Extends 'public.tlo_assignments' with foreign keys 'position_id', 'tlo_masterlist_id',
--      'capacity', and 'tlo_position_id' for position assignments management.
--   5. Backfills tlo_assignments.tlo_masterlist_id from tlo_masterlist using tloid matching.
--   6. Creates performance indexes on all relational columns.
--
-- Safety & Rollback:
--   - Fully wrapped in a transaction block (BEGIN / COMMIT).
--   - Safe idempotent execution with IF NOT EXISTS checks.
--   - Preserves all existing assignment and demographic data.
--   - Rollback instructions provided at the end of this file.
-- =========================================================================================

BEGIN;

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. Create tlo_positions Master Table
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.tlo_positions (
    id SERIAL PRIMARY KEY,
    position_title VARCHAR(150) NOT NULL,
    position_code VARCHAR(100) NULL,
    salary_grade VARCHAR(20) NULL,
    region VARCHAR(255) NULL,
    division VARCHAR(255) NULL,
    bureau VARCHAR(255) NULL,
    description TEXT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes on tlo_positions
CREATE INDEX IF NOT EXISTS idx_tlo_positions_title ON public.tlo_positions USING btree (position_title);
CREATE INDEX IF NOT EXISTS idx_tlo_positions_code ON public.tlo_positions USING btree (position_code);
CREATE INDEX IF NOT EXISTS idx_tlo_positions_region ON public.tlo_positions USING btree (region);
CREATE INDEX IF NOT EXISTS idx_tlo_positions_division ON public.tlo_positions USING btree (division);
CREATE INDEX IF NOT EXISTS idx_tlo_positions_bureau ON public.tlo_positions USING btree (bureau);

COMMENT ON TABLE public.tlo_positions IS 'Master inventory of official third level positions, stations, and salary grades';

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Populate tlo_positions Canonical Inventory
-- ─────────────────────────────────────────────────────────────────────────────
ON CONFLICT (id) DO UPDATE SET
    position_title = EXCLUDED.position_title,
    position_code = EXCLUDED.position_code,
    salary_grade = EXCLUDED.salary_grade,
    region = EXCLUDED.region,
    division = EXCLUDED.division,
    bureau = EXCLUDED.bureau,
    description = EXCLUDED.description;

SELECT setval('public.tlo_positions_id_seq', COALESCE((SELECT MAX(id) FROM public.tlo_positions), 1));

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. Extend tlo_assignments Table
-- ─────────────────────────────────────────────────────────────────────────────
ALTER TABLE public.tlo_assignments
    ADD COLUMN IF NOT EXISTS position_id INTEGER REFERENCES public.tlo_positions(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS capacity VARCHAR(20) NOT NULL DEFAULT 'Full',
    ADD COLUMN IF NOT EXISTS tlo_masterlist_id INTEGER REFERENCES public.tlo_masterlist(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS tlo_position_id VARCHAR(255);

-- Performance and lookup indexes
CREATE INDEX IF NOT EXISTS idx_tlo_assignments_masterlist ON public.tlo_assignments(tlo_masterlist_id);
CREATE INDEX IF NOT EXISTS idx_tlo_assignments_position_id ON public.tlo_assignments(position_id);
CREATE INDEX IF NOT EXISTS idx_tlo_assignments_capacity ON public.tlo_assignments(capacity);

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. Backfill Relational Links on tlo_assignments
-- ─────────────────────────────────────────────────────────────────────────────
UPDATE public.tlo_assignments a
SET tlo_masterlist_id = m.id
FROM public.tlo_masterlist m
WHERE a.tlo_masterlist_id IS NULL
  AND LOWER(TRIM(a.item_number)) = LOWER(TRIM(m.tloid));

COMMIT;

