-- ALTER TABLE public.tlo_assignments DROP COLUMN IF EXISTS capacity CASCADE;
-- ALTER TABLE public.tlo_assignments DROP COLUMN IF EXISTS tlo_masterlist_id CASCADE;
-- ALTER TABLE public.tlo_assignments DROP COLUMN IF EXISTS tlo_position_id CASCADE;
-- DROP TABLE IF EXISTS public.tlo_positions CASCADE;
-- COMMIT;
-- =========================================================================================
